/*!\brief Function to set unit's laplacian and class buffer.
 * \param[in]  i_min                The pos of the block's top boundary
 * \param[in]  i_max                The pos of the block's bottom boundary
 * \param[in]  j_min                The pos of the block's left boundary
 * \param[in]  j_max                The pos of the block's right boundary
 * \param[in]  stripe_size          The size of gdf unit stripe.
 * \param[in]  rec_pnt              Frame reconstruction data (pointing at the
 *                                  top-leftcorner of the unit)
 * \param[in]  rec_stride           Stride of \c rec_pnt
 * \param[in]  bit_depth            Bit-depth of the video
 * \param[in]  gdf_lap_y,           Array of the buffer where the results,
 *                                  laplacian data of the block, will be
 *                                  written. (array order : ver, hor,
 *                                  dia0 and dia1)
 * \param[in]  gdf_lap_y_stride     Stride of \c gdf_lap_y
 * \param[in]  gdf_cls_y            Buffer where the results, pixel class data
 *                                  of the block, will be written.
 * \param[in]  gdf_lap_y_stride     Stride of \c gdf_cls_y
 */
static void gdf_set_lap_and_cls_unit_c(const int i_min, const int i_max,
                                const int j_min, const int j_max,
                                const uint16_t *rec_pnt, const int rec_stride,
                                const int bit_depth, uint16_t *const *gdf_lap_y,
                                const int gdf_lap_y_stride, uint32_t *gdf_cls_y,
                                const int gdf_cls_y_stride) {
  const int blk_height = i_max - i_min;
  const int blk_width = j_max - j_min;
  const uint16_t *rec_y = rec_pnt;
  const int rec_y_stride = rec_stride;

  const int offset_ver = rec_y_stride, offset_dia0 = rec_y_stride + 1,
            offset_dia1 = rec_y_stride - 1;
  const int clip_mask =
      (1 << (16 - (GDF_TEST_INP_PREC - AVMMIN(bit_depth, GDF_TEST_INP_PREC)))) -
      1;
  const int lap_cls_height = (blk_height >> 1);

  const int lap_y_stride = gdf_lap_y_stride >> 1;
  uint32_t *above_line[GDF_NET_INP_GRD_NUM], *cur_line[GDF_NET_INP_GRD_NUM];
  gdf_cls_y += gdf_cls_y_stride * lap_cls_height;

  for (int grd_idx = 0; grd_idx < GDF_NET_INP_GRD_NUM; grd_idx++) {
    above_line[grd_idx] =
        (uint32_t *)(gdf_lap_y[grd_idx]) + lap_y_stride * (lap_cls_height - 1);
    cur_line[grd_idx] =
        (uint32_t *)(gdf_lap_y[grd_idx]) + lap_y_stride * (lap_cls_height);
  }

  const int16_t *std_pos = (int16_t *)(rec_y + blk_height * rec_y_stride);
  const int16_t *std_pos_1;
  const int16_t *std_pos0;
  const int16_t *std_pos1;
  const int16_t *std_pos2;
  std_pos_1 = std_pos - rec_stride;
  std_pos0 = std_pos;
  std_pos1 = std_pos0 + rec_stride;
  std_pos2 = std_pos1 + rec_stride;
  const int16_t *y00 = std_pos0;
  const int16_t *y10 = std_pos1;
  const int16_t *y_10 = std_pos_1;
  const int16_t *y20 = std_pos2;

  const int16_t *y0_1 = std_pos0 - 1;
  const int16_t *y01 = std_pos0 + 1;
  const int16_t *y1_1 = std_pos1 - 1;
  const int16_t *y11 = std_pos1 + 1;

  const int16_t *y_1_1 = std_pos_1 - 1;
  const int16_t *y21 = std_pos2 + 1;

  const int16_t *y_11 = std_pos_1 + 1;
  const int16_t *y2_1 = std_pos2 - 1;

  above_line[GDF_VER][0] = abs((y00[0] << 1) - y_10[0] - y10[0]) +
                           abs((y10[0] << 1) - y00[0] - y20[0]) +
                           abs((y00[1] << 1) - y_10[1] - y10[1]) +
                           abs((y10[1] << 1) - y00[1] - y20[1]);
  above_line[GDF_HOR][0] = abs((y00[0] << 1) - y0_1[0] - y01[0]) +
                           abs((y10[0] << 1) - y1_1[0] - y11[0]) +
                           abs((y00[1] << 1) - y0_1[1] - y01[1]) +
                           abs((y10[1] << 1) - y1_1[1] - y11[1]);
  above_line[GDF_DIAG0][0] = abs((y00[0] << 1) - y_1_1[0] - y11[0]) +
                             abs((y10[0] << 1) - y0_1[0] - y21[0]) +
                             abs((y00[1] << 1) - y_1_1[1] - y11[1]) +
                             abs((y10[1] << 1) - y0_1[1] - y21[1]);
  above_line[GDF_DIAG1][0] = abs((y00[0] << 1) - y_11[0] - y1_1[0]) +
                             abs((y10[0] << 1) - y01[0] - y2_1[0]) +
                             abs((y00[1] << 1) - y_11[1] - y1_1[1]) +
                             abs((y10[1] << 1) - y01[1] - y2_1[1]);
  for (int j0 = 2; j0 <= blk_width; j0 += 2) {
    int j1 = j0 + 1;
    int j00 = (j0 - 2) >> 1;
    int j01 = j00 + 1;
    above_line[GDF_VER][j00] += above_line[GDF_VER][j01] =
        abs((y00[j0] << 1) - y_10[j0] - y10[j0]) +
        abs((y10[j0] << 1) - y00[j0] - y20[j0]) +
        abs((y00[j1] << 1) - y_10[j1] - y10[j1]) +
        abs((y10[j1] << 1) - y00[j1] - y20[j1]);
    above_line[GDF_HOR][j00] += above_line[GDF_HOR][j01] =
        abs((y00[j0] << 1) - y0_1[j0] - y01[j0]) +
        abs((y10[j0] << 1) - y1_1[j0] - y11[j0]) +
        abs((y00[j1] << 1) - y0_1[j1] - y01[j1]) +
        abs((y10[j1] << 1) - y1_1[j1] - y11[j1]);
    above_line[GDF_DIAG0][j00] += above_line[GDF_DIAG0][j01] =
        abs((y00[j0] << 1) - y_1_1[j0] - y11[j0]) +
        abs((y10[j0] << 1) - y0_1[j0] - y21[j0]) +
        abs((y00[j1] << 1) - y_1_1[j1] - y11[j1]) +
        abs((y10[j1] << 1) - y0_1[j1] - y21[j1]);
    above_line[GDF_DIAG1][j00] += above_line[GDF_DIAG1][j01] =
        abs((y00[j0] << 1) - y_11[j0] - y1_1[j0]) +
        abs((y10[j0] << 1) - y01[j0] - y2_1[j0]) +
        abs((y00[j1] << 1) - y_11[j1] - y1_1[j1]) +
        abs((y10[j1] << 1) - y01[j1] - y2_1[j1]);
  }

  for (int i = (lap_cls_height - 1); i >= 0; i--) {
    std_pos -= (rec_y_stride << 1);
    gdf_cls_y -= gdf_cls_y_stride;

    for (int grd_idx = 0; grd_idx < GDF_NET_INP_GRD_NUM; grd_idx++) {
      above_line[grd_idx] -= lap_y_stride;
      cur_line[grd_idx] -= lap_y_stride;
    }
    y00 = std_pos;
    y10 = std_pos + offset_ver;
    y_10 = std_pos - offset_ver;
    y20 = std_pos + offset_ver + offset_ver;

    y0_1 = std_pos - 1;
    y01 = std_pos + 1;
    y1_1 = std_pos + offset_ver - 1;
    y11 = std_pos + offset_ver + 1;

    y_1_1 = std_pos - offset_dia0;
    y21 = std_pos + offset_ver + offset_dia0;

    y_11 = std_pos - offset_dia1;
    y2_1 = std_pos + offset_ver + offset_dia1;
    if (i == 0) {
      cur_line[GDF_VER][0] += abs((y00[0] << 1) - y_10[0] - y10[0]) +
                              abs((y10[0] << 1) - y00[0] - y20[0]) +
                              abs((y00[1] << 1) - y_10[1] - y10[1]) +
                              abs((y10[1] << 1) - y00[1] - y20[1]);
      cur_line[GDF_HOR][0] += abs((y00[0] << 1) - y0_1[0] - y01[0]) +
                              abs((y10[0] << 1) - y1_1[0] - y11[0]) +
                              abs((y00[1] << 1) - y0_1[1] - y01[1]) +
                              abs((y10[1] << 1) - y1_1[1] - y11[1]);
      cur_line[GDF_DIAG0][0] += abs((y00[0] << 1) - y_1_1[0] - y11[0]) +
                                abs((y10[0] << 1) - y0_1[0] - y21[0]) +
                                abs((y00[1] << 1) - y_1_1[1] - y11[1]) +
                                abs((y10[1] << 1) - y0_1[1] - y21[1]);
      cur_line[GDF_DIAG1][0] += abs((y00[0] << 1) - y_11[0] - y1_1[0]) +
                                abs((y10[0] << 1) - y01[0] - y2_1[0]) +
                                abs((y00[1] << 1) - y_11[1] - y1_1[1]) +
                                abs((y10[1] << 1) - y01[1] - y2_1[1]);
      for (int j0 = 2; j0 <= blk_width; j0 += 2) {
        int j1 = j0 + 1;
        int j00 = (j0 - 2) >> 1;
        int j01 = j00 + 1;
        uint32_t tmp_v = abs((y00[j0] << 1) - y_10[j0] - y10[j0]) +
                         abs((y10[j0] << 1) - y00[j0] - y20[j0]) +
                         abs((y00[j1] << 1) - y_10[j1] - y10[j1]) +
                         abs((y10[j1] << 1) - y00[j1] - y20[j1]);
        uint32_t tmp_h = abs((y00[j0] << 1) - y0_1[j0] - y01[j0]) +
                         abs((y10[j0] << 1) - y1_1[j0] - y11[j0]) +
                         abs((y00[j1] << 1) - y0_1[j1] - y01[j1]) +
                         abs((y10[j1] << 1) - y1_1[j1] - y11[j1]);
        uint32_t tmp_d0 = abs((y00[j0] << 1) - y_1_1[j0] - y11[j0]) +
                          abs((y10[j0] << 1) - y0_1[j0] - y21[j0]) +
                          abs((y00[j1] << 1) - y_1_1[j1] - y11[j1]) +
                          abs((y10[j1] << 1) - y0_1[j1] - y21[j1]);
        uint32_t tmp_d1 = abs((y00[j0] << 1) - y_11[j0] - y1_1[j0]) +
                          abs((y10[j0] << 1) - y01[j0] - y2_1[j0]) +
                          abs((y00[j1] << 1) - y_11[j1] - y1_1[j1]) +
                          abs((y10[j1] << 1) - y01[j1] - y2_1[j1]);

        cur_line[GDF_VER][j00] += tmp_v;
        cur_line[GDF_HOR][j00] += tmp_h;
        cur_line[GDF_DIAG0][j00] += tmp_d0;
        cur_line[GDF_DIAG1][j00] += tmp_d1;

        cur_line[GDF_VER][j01] += tmp_v;
        cur_line[GDF_HOR][j01] += tmp_h;
        cur_line[GDF_DIAG0][j01] += tmp_d0;
        cur_line[GDF_DIAG1][j01] += tmp_d1;

        cur_line[GDF_VER][j00] &= clip_mask;
        cur_line[GDF_HOR][j00] &= clip_mask;
        cur_line[GDF_DIAG1][j00] &= clip_mask;
        cur_line[GDF_DIAG0][j00] &= clip_mask;

        gdf_cls_y[j00] =
            (cur_line[GDF_VER][j00] > cur_line[GDF_HOR][j00] ? 0 : 1) |
            (cur_line[GDF_DIAG0][j00] > cur_line[GDF_DIAG1][j00] ? 0 : 2);

        cur_line[GDF_HOR][j00] |= (cur_line[GDF_HOR][j00] << 16);
        cur_line[GDF_VER][j00] |= (cur_line[GDF_VER][j00] << 16);
        cur_line[GDF_DIAG0][j00] |= (cur_line[GDF_DIAG0][j00] << 16);
        cur_line[GDF_DIAG1][j00] |= (cur_line[GDF_DIAG1][j00] << 16);
      }
    } else {
      above_line[GDF_VER][0] = abs((y00[0] << 1) - y_10[0] - y10[0]) +
                               abs((y10[0] << 1) - y00[0] - y20[0]) +
                               abs((y00[1] << 1) - y_10[1] - y10[1]) +
                               abs((y10[1] << 1) - y00[1] - y20[1]);
      above_line[GDF_HOR][0] = abs((y00[0] << 1) - y0_1[0] - y01[0]) +
                               abs((y10[0] << 1) - y1_1[0] - y11[0]) +
                               abs((y00[1] << 1) - y0_1[1] - y01[1]) +
                               abs((y10[1] << 1) - y1_1[1] - y11[1]);
      above_line[GDF_DIAG0][0] = abs((y00[0] << 1) - y_1_1[0] - y11[0]) +
                                 abs((y10[0] << 1) - y0_1[0] - y21[0]) +
                                 abs((y00[1] << 1) - y_1_1[1] - y11[1]) +
                                 abs((y10[1] << 1) - y0_1[1] - y21[1]);
      above_line[GDF_DIAG1][0] = abs((y00[0] << 1) - y_11[0] - y1_1[0]) +
                                 abs((y10[0] << 1) - y01[0] - y2_1[0]) +
                                 abs((y00[1] << 1) - y_11[1] - y1_1[1]) +
                                 abs((y10[1] << 1) - y01[1] - y2_1[1]);
      for (int j0 = 2; j0 <= blk_width; j0 += 2) {
        int j1 = j0 + 1;
        int j00 = (j0 - 2) >> 1;
        int j01 = j00 + 1;
        cur_line[GDF_VER][j00] += above_line[GDF_VER][j00] +=
            above_line[GDF_VER][j01] =
                abs((y00[j0] << 1) - y_10[j0] - y10[j0]) +
                abs((y10[j0] << 1) - y00[j0] - y20[j0]) +
                abs((y00[j1] << 1) - y_10[j1] - y10[j1]) +
                abs((y10[j1] << 1) - y00[j1] - y20[j1]);
        cur_line[GDF_HOR][j00] += above_line[GDF_HOR][j00] +=
            above_line[GDF_HOR][j01] =
                abs((y00[j0] << 1) - y0_1[j0] - y01[j0]) +
                abs((y10[j0] << 1) - y1_1[j0] - y11[j0]) +
                abs((y00[j1] << 1) - y0_1[j1] - y01[j1]) +
                abs((y10[j1] << 1) - y1_1[j1] - y11[j1]);
        cur_line[GDF_DIAG0][j00] += above_line[GDF_DIAG0][j00] +=
            above_line[GDF_DIAG0][j01] =
                abs((y00[j0] << 1) - y_1_1[j0] - y11[j0]) +
                abs((y10[j0] << 1) - y0_1[j0] - y21[j0]) +
                abs((y00[j1] << 1) - y_1_1[j1] - y11[j1]) +
                abs((y10[j1] << 1) - y0_1[j1] - y21[j1]);
        cur_line[GDF_DIAG1][j00] += above_line[GDF_DIAG1][j00] +=
            above_line[GDF_DIAG1][j01] =
                abs((y00[j0] << 1) - y_11[j0] - y1_1[j0]) +
                abs((y10[j0] << 1) - y01[j0] - y2_1[j0]) +
                abs((y00[j1] << 1) - y_11[j1] - y1_1[j1]) +
                abs((y10[j1] << 1) - y01[j1] - y2_1[j1]);

        cur_line[GDF_VER][j00] &= clip_mask;
        cur_line[GDF_HOR][j00] &= clip_mask;
        cur_line[GDF_DIAG1][j00] &= clip_mask;
        cur_line[GDF_DIAG0][j00] &= clip_mask;

        gdf_cls_y[j00] =
            (cur_line[GDF_VER][j00] > cur_line[GDF_HOR][j00] ? 0 : 1) |
            (cur_line[GDF_DIAG0][j00] > cur_line[GDF_DIAG1][j00] ? 0 : 2);

        cur_line[GDF_HOR][j00] |= (cur_line[GDF_HOR][j00] << 16);
        cur_line[GDF_VER][j00] |= (cur_line[GDF_VER][j00] << 16);
        cur_line[GDF_DIAG0][j00] |= (cur_line[GDF_DIAG0][j00] << 16);
        cur_line[GDF_DIAG1][j00] |= (cur_line[GDF_DIAG1][j00] << 16);
      }
    }
  }
}

/*!\brief Function to apply scaling factor to expected coding error
 *        and then generate the final filtered unit
 */
static void gdf_compensation_unit_c(uint16_t *rec_pnt, const int rec_stride,
                             int16_t *err_pnt, const int err_stride,
                             const int err_shift, const int scale,
                             const int pxl_max, const int blk_height,
                             const int blk_width) {
  const int errShift_half = err_shift > 0 ? 1 << (err_shift - 1) : 0;
  for (int i = 0; i < blk_height; i++) {
    for (int j = 0; j < blk_width; j++) {
      int res_pxl = scale * (*(err_pnt + j));
      if (res_pxl > 0) {
        res_pxl = (res_pxl + errShift_half) >> err_shift;
      } else {
        res_pxl = -(((-res_pxl) + errShift_half) >> err_shift);
      }
      rec_pnt[j] = (uint16_t)CLIP(res_pxl + rec_pnt[j], 0, pxl_max);
    }
    rec_pnt += rec_stride;
    err_pnt += err_stride;
  }
}

#define GDF_NORM_IDX(_va)                                               \
  ((((_va) > 0)                                                         \
        ? (((gdf_idx_scale) * (_va) + (gdf_shift_half)) >> (gdf_shift)) \
        : (-(((gdf_idx_scale) * (-(_va)) + (gdf_shift_half)) >>         \
             (gdf_shift)))) -                                           \
   (gdf_idx_min))

/*!\brief Function to generate vertical/horizontal/mixed features
 *        and then lookup for expected coding error with the
 *        corresponding quantized features
 */
static void gdf_inference_unit_c(const int i_min, const int i_max, const int j_min,
                          const int j_max, const int qp_idx,
                          const uint16_t *rec_pnt, const int rec_stride,
                          uint16_t *const *gdf_lap_pnt,
                          const int gdf_lap_stride, const uint32_t *gdf_cls_pnt,
                          const int gdf_cls_stride, int16_t *err_pnt,
                          const int err_stride, const int pxl_shift, const int ref_idx) {
  const int blk_height = i_max - i_min;
  const int blk_width = j_max - j_min;
  const int gdf_shift_value = pxl_shift;
  const uint16_t *rec_y = rec_pnt;
  const int rec_y_stride = rec_stride;
  const int res_y_stride = err_stride;
  const int gdf_frm_max = ref_idx ? GDF_NET_LUT_IDX_INTER_MAX : GDF_NET_LUT_IDX_INTRA_MAX;
  const int gdf_idx_min = -(gdf_frm_max >> 1);
  const int gdf_idx_max = gdf_frm_max - 1 + gdf_idx_min;
  const int gdf_idx_scale = AVMMAX(-gdf_idx_min, gdf_idx_max);
  int32_t gdf_shift =
      GDF_TEST_INP_PREC - GDF_TRAIN_INP_PREC + GDF_TRAIN_PAR_SCALE_LOG2;
  int32_t gdf_shift_half = 1 << (gdf_shift - 1);

  uint16_t *copied_lap_pnt[GDF_NET_INP_GRD_NUM];
  memcpy(copied_lap_pnt, gdf_lap_pnt, sizeof(copied_lap_pnt));
  const int16_t *alpha, *weight;
  const int32_t *bias;
  const int8_t *gdftable;
  alpha = ref_idx ? gdf_inter_alpha_table[ref_idx - 1][qp_idx] : gdf_intra_alpha_table[qp_idx];
  weight = ref_idx ? gdf_inter_weight_table[ref_idx - 1][qp_idx] : gdf_intra_weight_table[qp_idx];
  bias = ref_idx ? gdf_inter_bias_table[ref_idx - 1][qp_idx] : gdf_intra_bias_table[qp_idx];
  gdftable = ref_idx ? gdf_inter_error_table[ref_idx - 1][qp_idx] : gdf_intra_error_table[qp_idx];
  const uint32_t *cls_line = gdf_cls_pnt;
  int gdf_idx_offset[GDF_NET_LUT_IDX_NUM];
  for (int idx = 0; idx < GDF_NET_LUT_IDX_NUM; idx++) {
    gdf_idx_offset[idx] = 1;
    for (int r_idx = 0; r_idx < GDF_NET_LUT_IDX_NUM - 1 - idx; r_idx++) {
      gdf_idx_offset[idx] *= gdf_frm_max;
    }
  }
  const int16_t *rec_ptr = (const int16_t *)(rec_y);
  const int16_t *s_pos_fwd = 0, *s_pos_bwd = 0;
  for (int i = 0; i < blk_height; i++) {
    int32_t gdf_idx[GDF_BLOCK_PADDED][GDF_NET_LUT_IDX_NUM] = { 0 };
    for (int k = 0; k < GDF_OPTS_INP_TOT; k++) {
      if (k < GDF_NET_INP_REC_NUM) {
        s_pos_fwd = rec_ptr +
                    (gdf_guided_sample_coordinates_fwd[k][0] * rec_stride) +
                    gdf_guided_sample_coordinates_fwd[k][1];
        s_pos_bwd = rec_ptr +
                    (gdf_guided_sample_coordinates_bwd[k][0] * rec_stride) +
                    gdf_guided_sample_coordinates_bwd[k][1];
      }
      for (int j = 0; j < blk_width; j++) {
        uint32_t cls_idx = cls_line[j >> 1];
        const int32_t inp_value =
            k < GDF_NET_INP_REC_NUM
                ? (((s_pos_fwd[j] - rec_ptr[j]) * (1 << gdf_shift_value)))
                : (((copied_lap_pnt[k - GDF_NET_INP_REC_NUM][j])
                    << gdf_shift_value) >>
                   GDF_TRAIN_GRD_SHIFT);
        const int cls_offset = k * GDF_TRAIN_CLS_NUM + cls_idx;

        int32_t gdf_inp =
            CLIP(inp_value, -alpha[cls_offset], alpha[cls_offset]);

        if (k < GDF_NET_INP_REC_NUM) {
          const int32_t inp_value2 =
              (s_pos_bwd[j] - rec_ptr[j]) * (1 << gdf_shift_value);
          gdf_inp += CLIP(inp_value2, -alpha[cls_offset], alpha[cls_offset]);
        }
        gdf_inp = CLIP(gdf_inp, -(1 << (GDF_TEST_INP_PREC - 1)),
                       (1 << (GDF_TEST_INP_PREC - 1)) - 1);
        for (int idx = 0; idx < GDF_NET_LUT_IDX_NUM; idx++) {
          gdf_idx[j][idx] +=
              gdf_inp *
              (int32_t)weight[cls_offset +
                              (GDF_OPTS_INP_TOT * GDF_TRAIN_CLS_NUM) * idx];
        }
        if (k == (GDF_OPTS_INP_TOT - 1)) {
          const int8_t *tb_ptr = gdftable;
          for (int idx = 0; idx < GDF_NET_LUT_IDX_NUM; idx++) {
            gdf_idx[j][idx] += bias[cls_idx + GDF_TRAIN_CLS_NUM * idx];
            const int32_t tmp_gdf_idx = GDF_NORM_IDX(gdf_idx[j][idx]);
            tb_ptr +=
                CLIP(tmp_gdf_idx, 0, gdf_frm_max - 1) * gdf_idx_offset[idx];
          }

          err_pnt[j] = (int16_t)*tb_ptr;
        }
      }
    }
    if (i & 1) {
      cls_line += gdf_cls_stride;
      for (int grd_idx = 0; grd_idx < GDF_NET_INP_GRD_NUM; grd_idx++) {
        copied_lap_pnt[grd_idx] += gdf_lap_stride;
      }
    }
    rec_ptr += rec_y_stride;
    err_pnt += res_y_stride;
  }
}

uint16_t* svt_av2_gdf_copy_luma(const SvtAv2FrameBuffer* frame) {
    const size_t width = frame->visible_width, height = frame->visible_height;
    const uint32_t depth = frame->bit_depth, step = depth > 8u ? 2u : 1u;
    uint16_t* samples = (uint16_t*)malloc(width * height * sizeof(*samples));
    if (!samples) return NULL;
    for (size_t y = 0; y < height; ++y)
        for (size_t x = 0; x < width; ++x)
            samples[y * width + x] = svt_av2_sample_load(
                frame->planes[0] + y * frame->strides[0] + x * step, depth);
    return samples;
}

SvtAv2Error svt_av2_gdf_luma(SvtAv2FrameBuffer* frame, const uint16_t* guide,
    const uint16_t* deblocked, uint32_t base_q_idx, uint32_t code, uint32_t ref_distance) {
    enum { unit = 64, border = 6, stride = unit + 2 * border, lap_stride = unit + 16 };
    if (!frame || !guide || code < 1u || code > 16u) return SVT_AV2_ERROR_INVALID_PARAMETER;
    const int width = (int)frame->visible_width, height = (int)frame->visible_height;
    const int depth = (int)frame->bit_depth, step = depth == 10 ? 2 : 1;
    const int qp = (int)base_q_idx - 24 * (depth - 8);
    const int ref_idx = !ref_distance ? 0 : ref_distance < 2 ? 1 : ref_distance < 3 ? 2 :
        ref_distance < 6 ? 3 : ref_distance < 11 ? 4 : 5;
    const int key_qp = ref_distance ? qp - 25 : qp;
    const int model = (key_qp >= 172 ? 2 : key_qp >= 147 ? 1 : 0) + (int)(code - 1u) / 4;
    const int scale = 1 + (int)(code - 1u) % 4;
    uint16_t padded[stride * stride], lap_data[4][34 * lap_stride] = {{0}};
    uint16_t* lap[4] = { lap_data[0], lap_data[1], lap_data[2], lap_data[3] };
    uint32_t classes[34 * lap_stride] = {0};
    int16_t error[unit * lap_stride] = {0};
    uint16_t output[unit * unit];
    if (!deblocked) deblocked = guide;
    for (int stripe = -8; stripe < height; stripe += unit) {
        const int top = AVMMAX(0, stripe), bottom = AVMMIN(height, stripe + unit);
        const int h = bottom - top;
        for (int x0 = 0; x0 < width; x0 += unit) {
            const int w = AVMMIN(unit, width - x0);
            for (int y = -border; y < h + border; ++y) {
                const int inside = y >= 0 && y < h;
                const int row = CLIP(top + y, AVMMAX(0, top - 2), AVMMIN(height - 1, bottom + 1));
                const uint16_t* line = (inside || (row == 0 && top == 0) ||
                    (row == height - 1 && bottom == height) ? guide : deblocked) + (size_t)row * width;
                for (int x = -border; x < w + border; ++x)
                    padded[(y + border) * stride + x + border] = line[CLIP(x0 + x, 0, width - 1)];
            }
            uint16_t* center = padded + border * stride + border;
            gdf_set_lap_and_cls_unit_c(0, h, 0, w, center - stride - 1, stride,
                depth, lap, lap_stride, classes, lap_stride);
            gdf_inference_unit_c(0, h, 0, w, model, center, stride, lap, lap_stride,
                classes, lap_stride, error, lap_stride, 10 - depth, ref_idx);
            for (int y = 0; y < h; ++y)
                for (int x = 0; x < w; ++x)
                    output[y * unit + x] = svt_av2_sample_load(frame->planes[0] +
                        (size_t)(top + y) * frame->strides[0] + (x0 + x) * step, frame->bit_depth);
            gdf_compensation_unit_c(output, unit, error, lap_stride, 12 - depth, scale,
                (1 << depth) - 1, h, w);
            for (int y = 0; y < h; ++y)
                for (int x = 0; x < w; ++x)
                    svt_av2_sample_store(frame->planes[0] + (size_t)(top + y) * frame->strides[0] +
                        (x0 + x) * step, frame->bit_depth, output[y * unit + x]);
        }
    }
    return SVT_AV2_ERROR_NONE;
}
